import json, sqlite3, os, re
from datetime import datetime, timezone

THREAD='01a144d2-ad1c-7fc1-bd5f-f4d0f2c1b5f8'
OUT_DIR='/Users/nabhag/Library/Application Support/Cursor/AgentStores/cursor_agent_stores/2618cc06-9dbe-4272-86fd-19770668b253/files'
state = sqlite3.connect('/Users/nabhag/.codex/state_5.sqlite')
hist = sqlite3.connect(f'file:/Users/nabhag/.codex/thread_history_1.sqlite?mode=ro', uri=True)

meta = state.execute("""
SELECT id, name, title, cwd, git_branch, git_sha, git_origin_url, rollout_path, model,
       datetime(created_at_ms/1000,'unixepoch') , datetime(updated_at_ms/1000,'unixepoch'), preview
FROM threads WHERE id=?
""", (THREAD,)).fetchone()

rows = hist.execute("""
SELECT turn_id, item_id, rollout_ordinal, created_at_ms, item_type, item_json
FROM thread_items
WHERE thread_id=?
ORDER BY rollout_ordinal ASC
""", (THREAD,)).fetchall()

def extract_text(obj):
    if obj is None: return ''
    if isinstance(obj, str): return obj
    if isinstance(obj, list):
        parts=[]
        for x in obj:
            if isinstance(x, str): parts.append(x)
            elif isinstance(x, dict):
                if 'text' in x: parts.append(str(x['text']))
                elif x.get('type') in ('text','input_text','output_text') and 'text' in x: parts.append(str(x['text']))
                elif 'content' in x: parts.append(extract_text(x['content']))
                else: parts.append(extract_text(x))
        return '\n'.join(p for p in parts if p)
    if isinstance(obj, dict):
        for k in ('text','content','message','body','markdown','value'):
            if k in obj: 
                t=extract_text(obj[k])
                if t: return t
        # nested common shapes
        if 'parts' in obj: return extract_text(obj['parts'])
        return ''
    return str(obj)

def summarize_item(item_type, data):
    # data is parsed json
    if item_type == 'userMessage':
        text = extract_text(data.get('content') or data.get('text') or data.get('message') or data)
        return ('user', text.strip())
    if item_type == 'agentMessage':
        text = extract_text(data.get('content') or data.get('text') or data.get('message') or data)
        return ('assistant', text.strip())
    if item_type == 'fileChange':
        # try to get paths
        paths=[]
        for k in ('changes','files','edits','path'):
            if k in data:
                v=data[k]
                if isinstance(v,str): paths.append(v)
                elif isinstance(v,list):
                    for it in v:
                        if isinstance(it,str): paths.append(it)
                        elif isinstance(it,dict):
                            paths.append(it.get('path') or it.get('file') or it.get('filename') or '')
        paths=[p for p in paths if p]
        summary = data.get('summary') or data.get('description') or ''
        return ('file_change', (summary + '\n' + '\n'.join(paths[:40])).strip())
    if item_type == 'commandExecution':
        cmd = data.get('command') or data.get('cmd') or data.get('shell_command') or ''
        if isinstance(cmd, list): cmd=' '.join(map(str,cmd))
        exit_code = data.get('exit_code') or data.get('exitCode') or data.get('status')
        # truncate output
        out = data.get('aggregated_output') or data.get('output') or data.get('stdout') or ''
        if isinstance(out, dict): out = extract_text(out)
        out = str(out)
        if len(out)>800: out=out[:400]+'\n...\n'+out[-400:]
        return ('command', f"$ {cmd}\nexit={exit_code}\n{out}".strip())
    if item_type == 'reasoning':
        text = extract_text(data.get('summary') or data.get('content') or data.get('text') or data)
        if len(text)>600: text=text[:600]+'...'
        return ('reasoning', text.strip())
    if item_type == 'webSearch':
        return ('web_search', extract_text(data)[:500])
    if item_type == 'contextCompaction':
        return ('compaction', 'context compacted')
    return (item_type, extract_text(data)[:500])

# Build full markdown transcript (user+assistant primary) and a compact context brief
dialogue=[]
actions=[]
for turn_id, item_id, ord_, created, itype, raw in rows:
    try:
        data=json.loads(raw)
    except Exception:
        data={'raw': raw[:200]}
    kind, text = summarize_item(itype, data if isinstance(data,dict) else {'content':data})
    if not text: continue
    ts = datetime.fromtimestamp(created/1000, tz=timezone.utc).isoformat()
    if kind in ('user','assistant'):
        dialogue.append({'ts':ts,'role':kind,'turn':turn_id,'text':text,'ordinal':ord_})
    elif kind in ('file_change','command','web_search','compaction'):
        actions.append({'ts':ts,'kind':kind,'turn':turn_id,'text':text[:2000],'ordinal':ord_})

# Write full dialogue
full_path=os.path.join(OUT_DIR,'refactor-around-sdk-protobuf-transcript.md')
with open(full_path,'w') as f:
    f.write(f"# Codex thread: {meta[1]}\n\n")
    f.write(f"- **id**: `{meta[0]}`\n")
    f.write(f"- **cwd**: `{meta[3]}`\n")
    f.write(f"- **branch**: `{meta[4]}`\n")
    f.write(f"- **git_sha**: `{meta[5]}`\n")
    f.write(f"- **origin**: `{meta[6]}`\n")
    f.write(f"- **model**: `{meta[8]}`\n")
    f.write(f"- **created**: {meta[9]}\n")
    f.write(f"- **updated**: {meta[10]}\n")
    f.write(f"- **rollout**: `{meta[7]}`\n")
    f.write(f"- **user/assistant messages**: {sum(1 for d in dialogue if d['role']=='user')}/{sum(1 for d in dialogue if d['role']=='assistant')}\n\n")
    f.write("---\n\n")
    for d in dialogue:
        role = 'USER' if d['role']=='user' else 'ASSISTANT'
        f.write(f"## {role} ({d['ts']})\n\n")
        f.write(d['text'])
        f.write("\n\n---\n\n")

# Also dump JSON for machine use
json_path=os.path.join(OUT_DIR,'refactor-around-sdk-protobuf-dialogue.json')
with open(json_path,'w') as f:
    json.dump({'meta':{
        'id':meta[0],'name':meta[1],'title':meta[2],'cwd':meta[3],'branch':meta[4],
        'sha':meta[5],'origin':meta[6],'rollout':meta[7],'model':meta[8],
        'created':meta[9],'updated':meta[10]
    },'dialogue':dialogue,'actions_count':len(actions)}, f)

print('dialogue messages', len(dialogue))
print('user', sum(1 for d in dialogue if d['role']=='user'))
print('assistant', sum(1 for d in dialogue if d['role']=='assistant'))
print('actions', len(actions))
print('full bytes', os.path.getsize(full_path))
print('wrote', full_path)

# Print user messages only (short index)
print('\n===== USER MESSAGE INDEX =====')
for i,d in enumerate([x for x in dialogue if x['role']=='user'],1):
    preview=re.sub(r'\s+',' ',d['text'])[:180]
    print(f"{i:02d}. [{d['ts']}] {preview}")
