source_open = re.compile(
    r'^(?P<indent>\s*)Source:\s*&sandbox\.SandboxSource\{Kind:\s*&sandbox\.SandboxSource_(?:Image|Snapshot|WarmPool|ProviderDefault)\{'
    r'(?:Image|Snapshot|WarmPool|ProviderDefault):\s*&sandbox\.(?:Image|Snapshot|WarmPool|ProviderDefault)Source\{(?P<inner>[^}]*)\}\s*\}\s*,\s*$'
)

for path in list(Path('examples/go').rglob('*.go')) + list(Path('sdks/go/providers').rglob('*.go')):
    lines = path.read_text().splitlines(True)
    changed = False
