        m = source_open.match(line)
        if not m:
            continue
        # peek next non-empty
        j = i + 1
        while j < len(lines) and lines[j].strip() == '':
            j += 1
        if j < len(lines) and sibling.match(lines[j]):
            # insert missing } before comma
