// Handwritten helpers for protobuf metadata objects (mirrors Go sandbox metadata helpers).

import type { MetadataObject, MetadataValue } from "./sandbox_data_contracts.js";

export type MetadataPlain =
  | null
  | boolean
  | string
  | number
  | bigint
  | Uint8Array
  | MetadataPlain[]
  | { [key: string]: MetadataPlain };

/** Converts a declarative map into the protobuf metadata object. */
export function metadataObjectFromMap(
  source: Record<string, MetadataPlain> | undefined,
): MetadataObject | undefined {
  if (source === undefined) return undefined;
  const values: { [key: string]: MetadataValue } = {};
  for (const [key, value] of Object.entries(source)) {
    values[key] = metadataValueFromPlain(value);
  }
  return { values };
}

/** Converts a protobuf metadata object into a declarative map. */
export function metadataObjectAsMap(
  source: MetadataObject | undefined,
): Record<string, MetadataPlain> | undefined {
  if (source === undefined) return undefined;
  const out: Record<string, MetadataPlain> = {};
  for (const [key, value] of Object.entries(source.values ?? {})) {
    out[key] = metadataValueAsPlain(value);
  }
  return out;
}

function metadataValueFromPlain(value: MetadataPlain): MetadataValue {
  if (value === null) return { value: { case: undefined } };
  if (typeof value === "boolean") return { value: { case: "boolean", value } };
  if (typeof value === "string") return { value: { case: "text", value } };
  if (typeof value === "bigint") {
    if (value < 0n) return { value: { case: "signedInteger", value } };
    return { value: { case: "unsignedInteger", value } };
  }
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new Error("sandbox-kit: metadata numbers must be finite");
    }
    if (Number.isInteger(value)) {
      const asBigInt = BigInt(value);
      if (value < 0) return { value: { case: "signedInteger", value: asBigInt } };
      return { value: { case: "unsignedInteger", value: asBigInt } };
    }
    return { value: { case: "number", value } };
  }
  if (value instanceof Uint8Array) return { value: { case: "binary", value } };
  if (Array.isArray(value)) {
    return {
      value: {
        case: "list",
        value: { values: value.map(metadataValueFromPlain) },
      },
    };
  }
  return {
    value: {
      case: "object",
      value: metadataObjectFromMap(value) ?? { values: {} },
    },
  };
}

function metadataValueAsPlain(value: MetadataValue | undefined): MetadataPlain {
  if (value === undefined || value.value.case === undefined) return null;
  switch (value.value.case) {
    case "boolean":
    case "text":
    case "number":
    case "binary":
      return value.value.value;
    case "signedInteger":
    case "unsignedInteger":
      return value.value.value;
    case "list":
      return (value.value.value.values ?? []).map(metadataValueAsPlain);
    case "object":
      return metadataObjectAsMap(value.value.value) ?? {};
    default:
      return null;
  }
}

