function mapPolicyMinutes(
  policy: AutomaticAction | undefined,
  field: string,
  assign: (minutes: number) => void,
  options: { allowDisable?: boolean; allowZero?: boolean } = {},
): void {
  if (policy === undefined) return;
  const mode = policy.mode ?? PolicyMode.Default;
  if (mode === PolicyMode.Disabled) {
